FBindex:=AssociativeArray();for i in [1..m] do FBindex[fb[i]]:=i;end for;
function NewKey(xy)
 L:=Parent(xy[1]);dd:=Degree(L,k);vv:=[xy[1],xy[2],xy[1]+xy[2],xy[1]-xy[2]];
 zz:=[v:v in vv|Degree(MinimalPolynomial(v,k)) eq dd];assert #zz gt 0;th:=zz[1];
 BM:=Matrix(k,[Eltseq(th^i,k):i in [0..dd-1]]);IB:=BM^-1;
 return Sprint([Eltseq(MinimalPolynomial(th,k)),Eltseq(Vector(k,Eltseq(xy[1],k))*IB),Eltseq(Vector(k,Eltseq(xy[2],k))*IB)]);
end function;
function RatER(q)return [Eltseq(Numerator(q)),Eltseq(Denominator(q))];end function;
function FER(q)return [RatER(a):a in Eltseq(q)];end function;
function SmoothClass(Q)
 for extra in [0..8] do
  A:=(ExpectedGenus+Degree(Q)+extra)*Divisor(fb[ic0]);
  BS:=Basis(A-Divisor(Q):Reduction:=false,Simplification:="None");assert #BS gt 0;
  for attempt in [1..12] do
   ff:=attempt le #BS select BS[attempt] else &+[Random(k)*g:g in BS];if ff eq 0 then continue;end if;
   RR:=Divisor(ff)+A-Divisor(Q);assert IsEffective(RR) and Degree(RR) eq ExpectedGenus+extra;
   ps,es:=Support(RR);if not &and[IsDefined(FBindex,V):V in ps] then continue;end if;
   ii:=[FBindex[V]:V in ps];cl:=[* *];
   for j in [1..#Mods] do Append(~cl,-&+[CG[j]|es[z]*CC[j][ii[z]]:z in [1..#ii]]);end for;
   return cl,[*extra,FER(ff),ii,es*];
  end for;
 end for;
 error "D31A_SMOOTHING_FAILED";
end function;
